def no_order(equation):
    if not equation:
        return None

    equation = equation.replace(' ', '')

    if '0' in equation and ('/' in equation or '%' in equation):
        return None

    operations = ['+', '-', '*', '/', '^', '%']
    for op in operations:
        equation = equation.replace(op, f' {op} ')

    equation = equation.split()

    result = float(equation[0])
    for i in range(1, len(equation), 2):
        op = equation[i]
        num = float(equation[i + 1])
        if op == '+':
            result += num
        elif op == '-':
            result -= num
        elif op == '*':
            result *= num
        elif op == '/':
            result = result // num
        elif op == '^':
            result = result ** num
        elif op == '%':
            result %= num

    return result

