                    b = stack.pop()
                    a = stack.pop()
                    op = stack.pop()
                    stack.append(eval(f"{a}{op}{b}"))
            stack.append(equation[i])
        else:
            j = i
            while j < len(equation) and equation[j] not in operators:
                j += 1
            stack.append(int(equation[i:j]))
            i = j - 1
        i += 1

    while len(stack) > 1:
