def repeat_sequence_len(n):
    def sum_of_squares(num):
        return sum(int(digit) ** 2 for digit in str(num))

    seen = {}
    current = n
    step = 0

    while current not in seen:
        seen[current] = step
        current = sum_of_squares(current)
        step += 1

    return step - seen[current]

